import {copyHTML,copyRaw} from './site-copy.js';
import {backend} from './backend.js';
import {subjects as defaults} from './data.js';
import {escape as e} from './store.js';
let rows=null,lastError='';
export const subjectCatalog={
 names(){return rows===null?defaults.filter(x=>x!=='All subjects'):rows.map(x=>x.name);},
 filters(){return ['All subjects',...this.names()];},
 options(current=''){const names=this.names();return current&&!names.includes(current)?[current,...names]:names;},
 rows:()=>rows||[],
 error:()=>lastError,
 async load(){try{const fetched=await backend.read('lexamah_subjects');if(!Array.isArray(fetched)||fetched.some(x=>!x||typeof x.name!=='string'))throw new Error(copyRaw("subjects.8a1f23c40389"));rows=fetched;rows.sort((a,b)=>a.name.localeCompare(b.name));lastError='';return rows;}catch(err){lastError=err.message;return null;}},
 async add(raw){const name=String(raw).trim().replace(/\s+/g,' ');if(!name||name.length>120)throw new Error(copyRaw("subjects.c140d1c17f14"));if(name.toLowerCase()==='all subjects')throw new Error(copyRaw("subjects.49d43ac5e0b8"));if(this.names().some(x=>x.toLowerCase()===name.toLowerCase()))throw new Error(copyRaw("subjects.85895542ae4a"));await backend.cloudSave('subjects',{name});await this.load();},
 async remove(id){await backend.cloudDelete('subjects',id);await this.load();}
};
export function subjectsScreen(){return `<section class="card"><div class="card-head"><div><h2>${copyHTML("subjects.03245fa14e82")}</h2><p>${copyHTML("subjects.308381170cf2")}</p></div><span class="pill">${subjectCatalog.rows().length} ${copyHTML("subjects.e223d8ec1e64")}</span></div>${subjectCatalog.error()?`<div class="notice">${copyHTML("subjects.a0304d65b61c")}</div>`:`<form id="subject-add-form" class="task-add"><input name="name" required maxlength="120" placeholder="${copyHTML("subjects.bfbea56bb5d6")}" aria-label="${copyHTML("subjects.9c69910bdf55")}"><button class="btn primary">${copyHTML("subjects.428012ea33be")}</button></form><p id="subject-status" class="muted" role="status"></p>${subjectCatalog.rows().length?subjectCatalog.rows().map(x=>`<div class="row"><div class="row-copy"><strong>${e(x.name)}</strong></div><button class="btn danger" data-remove-subject="${e(x.id)}">${copyHTML("subjects.c3812fc4acb8")}</button></div>`).join(''):`<p class="muted">${copyHTML("subjects.d701c626ee3d")}</p>`}`}<p class="muted">${copyHTML("subjects.c4185580c9f3")}</p></section>`;}
export function bindSubjects(ui){const form=document.querySelector('#subject-add-form');if(!form)return;form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('button');button.disabled=true;try{await subjectCatalog.add(new FormData(form).get('name'));await ui.reload();ui.render();ui.toast(copyRaw("subjects.8c170c0a9290"));}catch(err){document.querySelector('#subject-status').textContent=err.message;}finally{button.disabled=false;}};}
export function removeSubject(id,ui){const item=subjectCatalog.rows().find(x=>x.id===id);if(!item)return;ui.modal(copyRaw("subjects.d9f1c2357c34"),`<p class="muted">${copyHTML("subjects.5b7e3a54b292")}${e(item.name)}${copyHTML("subjects.13e9d55fb8f6")}</p><p id="subject-remove-status" class="muted" role="status"></p><div class="actions"><button class="btn danger" id="subject-confirm-remove">${copyHTML("subjects.42da752ea040")}</button><button class="btn" id="subject-cancel-remove">${copyHTML("subjects.0468117713d8")}</button></div>`);document.querySelector('#subject-cancel-remove').onclick=()=>document.querySelector('#dialog').close();document.querySelector('#subject-confirm-remove').onclick=async event=>{event.target.disabled=true;try{await subjectCatalog.remove(id);document.querySelector('#dialog').close();await ui.reload();ui.render();ui.toast(copyRaw("subjects.a045a1d41471"));}catch(err){document.querySelector('#subject-remove-status').textContent=err.message;event.target.disabled=false;}};}
